      const fx = 4 + Math.sin(T * 60 + ph) * 2;
      r('#ff7a24', u - 15 - fx, v + .6, fx, h - 1.2); r('#ffd24a', u - 15 - fx * .7, v + 1.1, fx * .7, h - 2.2); r('#fff6c8', u - 15 - fx * .3, v + 1.6, fx * .3, 1.2);
