      const id = pick(ids), [n0, n1, ec, v0, v1] = ESPECES_RECIF[id], n = irnd(n0, n1), lp = ((D.SPR[id] && D.SPR[id].l) || [30])[0] * { s: .46, m: .68, l: 1 }[R.tag] / S;
      const e = Math.max(ec * R.k, lp * .9) * Math.sqrt(n);
