      R(x, K, 0, c, w, h - c); R(x, '#4e525e', 0, c + 1, w, h - c - 2); R(x, '#7d828f', 0, c + 1, w, 1);
      for (let i = 3; i < w; i += 10) R(x, '#7d828f', i, c + 4, 2, 2);
