      for (let i = 0; i < 90; i++) { R(x, r() < .5 ? '#f0d478' : '#a88a34', 1 + r() * (w - 4) | 0, 1 + r() * (h - 3) | 0, 2 + r() * 3 | 0, 1); }
      for (const a of [(w * .28) | 0, (w * .72) | 0]) { R(x, '#6a4a22', a, 1, 2, h - 2); }
