    if (fin.rec) G.txt(x, 'RECORD !', cx - 50, 72, '#ffe27a', { al: .5, contour: K });
    x.drawImage(G.Rendu.bob[(G.t * 10 | 0) & 7], cx + 30, 50);
    G.txt(x, '+' + fin.bob, cx + 46, 52, '#ffe27a', { contour: K, sc: 2 });
